from pathlib import Path

p=Path('index.html')
s=p.read_text(encoding='utf-8')
old='<section id="view-absence" class="view"><div class="page-head"><div><div class="eyebrow">VERFÜGBARKEIT</div><h1>Abwesenheiten</h1><p>Urlaub, Krankheit und Sperrzeiten verwalten.</p></div></div><div class="card table-card" id="absencePanel"></div></section>'
new='''<section id="view-absence" class="view"><div class="page-head"><div><div class="eyebrow">VERFÜGBARKEIT</div><h1>Abwesenheiten</h1><p>Urlaub, Krankheit, Frei, Fortbildung und Sperrzeiten planen und Konflikte früh erkennen.</p></div><button class="primary" onclick="openAbsenceDialog()">＋ Abwesenheit eintragen</button></div><div class="stats" id="absenceStats"></div><div class="card table-card" style="margin-top:14px"><div class="table-head"><h3>Abwesenheiten verwalten</h3><select id="absencePeriod" onchange="renderAbsenceDashboard()"><option value="week">Diese Woche</option><option value="month">Dieser Monat</option><option value="all">Alle</option></select><select id="absenceTypeFilter" onchange="renderAbsenceDashboard()"><option value="">Alle Arten</option><option>Urlaub</option><option>Krank</option><option>Frei</option><option>Fortbildung</option><option>Sperrzeit</option><option>Sonderurlaub</option><option>Sonstiges</option></select></div><div id="absencePanel"></div></div><div class="panel-grid" style="margin-top:14px"><div class="card table-card"><div class="table-head"><h3>Wochenkalender</h3></div><div id="absenceCalendar"></div></div><div class="card table-card"><div class="table-head"><h3>Konflikte & Auswirkungen</h3><span class="badge" id="absenceConflictCount">0</span></div><div id="absenceConflicts"></div></div></div></section>'''
if old not in s: raise SystemExit('absence section not found')
s=s.replace(old,new)
addon=r'''
let absenceEditingId=null;
function absenceDates(a){const start=a.startDate||a.date,end=a.endDate||a.date||start;if(!start)return[];let d=new Date(start+'T00:00:00'),e=new Date(end+'T00:00:00'),out=[];while(d<=e){out.push(iso(d));d=addDays(d,1)}return out}
function absenceOn(a,date){return absenceDates(a).includes(date)}
function absenceStatus(a){return a.status||((a.type==='Krank')?'Erfasst':'Genehmigt')}
function openAbsenceDialog(id=null){absenceEditingId=id;const a=id?absences.find(x=>x.id===id):null;const empOptions=employees.filter(e=>e.status==='active').map(e=>`<option value="${e.id}" ${(a?.employeeId===e.id)?'selected':''}>${e.first} ${e.last}</option>`).join('');const html=`<div class="modal-backdrop" id="absenceModal"><div class="modal"><div class="modal-head"><h3>${a?'Abwesenheit bearbeiten':'Abwesenheit eintragen'}</h3><button class="iconbtn" onclick="document.getElementById('absenceModal').remove()">✕</button></div><div class="form"><label>Mitarbeiter<select id="absEmp">${empOptions}</select></label><div class="form-grid"><label>Von<input id="absStart" type="date" value="${a?.startDate||a?.date||iso(new Date())}"></label><label>Bis<input id="absEnd" type="date" value="${a?.endDate||a?.date||iso(new Date())}"></label></div><div class="form-grid"><label>Art<select id="absType">${['Urlaub','Krank','Frei','Fortbildung','Sperrzeit','Sonderurlaub','Sonstiges'].map(x=>`<option ${a?.type===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Status<select id="absStatus">${['Beantragt','Genehmigt','Erfasst','Abgelehnt'].map(x=>`<option ${absenceStatus(a||{})===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="form-grid"><label>Ganztägig<select id="absFull"><option value="1">Ja</option><option value="0" ${a?.fullDay===false?'selected':''}>Nein</option></select></label><label>Uhrzeit / Hinweis<input id="absTime" placeholder="z. B. ab 14:00" value="${a?.timeNote||''}"></label></div><label>Notiz<textarea id="absNote" rows="3">${a?.note||''}</textarea></label></div><div class="form-actions"><button class="ghost" onclick="document.getElementById('absenceModal').remove()">Abbrechen</button><button class="primary" onclick="saveAbsenceDialog()">Speichern</button></div></div></div>`;document.body.insertAdjacentHTML('beforeend',html)}
function saveAbsenceDialog(){const start=document.getElementById('absStart').value,end=document.getElementById('absEnd').value;if(!start||!end||end<start){alert('Bitte einen gültigen Zeitraum wählen.');return}const data={employeeId:document.getElementById('absEmp').value,startDate:start,endDate:end,date:start,type:document.getElementById('absType').value,status:document.getElementById('absStatus').value,fullDay:document.getElementById('absFull').value==='1',timeNote:document.getElementById('absTime').value.trim(),note:document.getElementById('absNote').value.trim()};if(absenceEditingId){Object.assign(absences.find(x=>x.id===absenceEditingId),data)}else absences.push({id:'a'+Date.now(),...data});saveAll();document.getElementById('absenceModal').remove();renderAbsenceDashboard();updateStats();showSaveToast('Abwesenheit gespeichert','Zeitraum und Status wurden übernommen.')}
function deleteAbsenceEnhanced(id){if(!confirm('Abwesenheit wirklich löschen?'))return;absences=absences.filter(a=>a.id!==id);saveAll();renderAbsenceDashboard();updateStats()}
function renderAbsenceDashboard(){const panel=document.getElementById('absencePanel');if(!panel)return;const period=document.getElementById('absencePeriod')?.value||'week',tf=document.getElementById('absenceTypeFilter')?.value||'';const wd=currentWeekDates().map(iso),month=iso(weekStart).slice(0,7);let list=absences.filter(a=>!tf||a.type===tf);if(period==='week')list=list.filter(a=>absenceDates(a).some(d=>wd.includes(d)));if(period==='month')list=list.filter(a=>absenceDates(a).some(d=>d.startsWith(month)));const today='2026-08-26';const todayCount=absences.filter(a=>absenceOn(a,today)&&absenceStatus(a)!=='Abgelehnt').length,weekCount=new Set(absences.filter(a=>absenceDates(a).some(d=>wd.includes(d))&&absenceStatus(a)!=='Abgelehnt').map(a=>a.employeeId)).size,urlaub=absences.filter(a=>a.type==='Urlaub'&&absenceStatus(a)!=='Abgelehnt').reduce((n,a)=>n+absenceDates(a).filter(d=>period==='all'||(period==='week'?wd.includes(d):d.startsWith(month))).length,0),krank=absences.filter(a=>a.type==='Krank'&&absenceStatus(a)!=='Abgelehnt').reduce((n,a)=>n+absenceDates(a).filter(d=>period==='all'||(period==='week'?wd.includes(d):d.startsWith(month))).length,0);document.getElementById('absenceStats').innerHTML=[[todayCount,'Heute abwesend'],[weekCount,'Diese Woche'],[urlaub,'Urlaubstage'],[krank,'Kranktage']].map((x,i)=>`<div class="stat"><div class="stat-icon">${['◉','▦','☀','✚'][i]}</div><div><small>${x[1]}</small><strong>${x[0]}</strong><em>${period==='week'?'aktuelle Woche':'gewählter Zeitraum'}</em></div></div>`).join('');panel.innerHTML=list.length?list.sort((a,b)=>(a.startDate||a.date).localeCompare(b.startDate||b.date)).map(a=>{const e=employees.find(x=>x.id===a.employeeId),dates=absenceDates(a),conf=assignments.filter(x=>x.employeeId===a.employeeId&&dates.includes(x.date));return `<div class="absence-item" style="margin-bottom:8px"><div><b>${e?e.first+' '+e.last:'Unbekannt'}</b><small style="display:block">${a.type} · ${new Date(dates[0]+'T00:00:00').toLocaleDateString('de-DE')} – ${new Date(dates[dates.length-1]+'T00:00:00').toLocaleDateString('de-DE')} ${a.timeNote?'· '+a.timeNote:''}</small>${conf.length?`<small style="color:#ffd08a">⚠ ${conf.length} Dienstplan-Konflikt${conf.length===1?'':'e'}</small>`:''}</div><div style="display:flex;align-items:center;gap:7px"><span class="pill ${absenceStatus(a)==='Genehmigt'||absenceStatus(a)==='Erfasst'?'good':absenceStatus(a)==='Abgelehnt'?'':'warn'}">${absenceStatus(a)}</span><button class="ghost" onclick="openAbsenceDialog('${a.id}')">Bearbeiten</button><button class="ghost" onclick="deleteAbsenceEnhanced('${a.id}')">Löschen</button></div></div>`}).join(''):'<div class="empty">Keine Abwesenheiten im gewählten Zeitraum.</div>';const cal=document.getElementById('absenceCalendar');cal.innerHTML=wd.map((d,i)=>{const aa=absences.filter(a=>absenceOn(a,d)&&absenceStatus(a)!=='Abgelehnt');return `<div class="absence-item"><div><b>${DAYS[i]} · ${new Date(d+'T00:00:00').toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit'})}</b><small>${aa.length?aa.map(a=>{const e=employees.find(x=>x.id===a.employeeId);return `${e?.first||''} ${e?.last||''} · ${a.type}`}).join('<br>'):'Keine Abwesenheit'}</small></div><span class="pill ${aa.length?'warn':'good'}">${aa.length}</span></div>`}).join('');const conflicts=[];absences.filter(a=>absenceStatus(a)!=='Abgelehnt').forEach(a=>{const e=employees.find(x=>x.id===a.employeeId);assignments.filter(x=>x.employeeId===a.employeeId&&absenceOn(a,x.date)).forEach(x=>conflicts.push({a,e,x}))});document.getElementById('absenceConflictCount').textContent=conflicts.length;document.getElementById('absenceConflicts').innerHTML=conflicts.length?conflicts.map(c=>`<div class="absence-item"><div><b>⚠ ${c.e?.first||''} ${c.e?.last||''}</b><small>${new Date(c.x.date+'T00:00:00').toLocaleDateString('de-DE')} · ${c.x.type} trotz ${c.a.type}</small></div><button class="ghost" onclick="showView('plan')">Dienstplan öffnen</button></div>`).join(''):'<div class="notice">✓ Keine Konflikte zwischen Abwesenheiten und Dienstplan gefunden.</div>'}
const _oldRenderAbsence=typeof renderAbsence==='function'?renderAbsence:null;renderAbsence=function(){renderAbsenceDashboard()};
'''
s=s.replace('\n</script>',addon+'\n</script>')
p.write_text(s,encoding='utf-8')
print('absence dashboard applied')
